  if(s==='jungleCommand'){const kind=['vine','spore','geyser'][(rana.sequence+rana.phase)%3];rana.command=kind;const n=rana.phase===1?2:3;for(let i=0;i<n;i++){const x=ranaClampX(rana.target.x+(i-(n-1)/2)*210,100),y=kind==='spore'?clamp(rana.target.y+(i%2?120:-90),400,730):865;ranaHazard(kind,x,y,1.15+i*.24,kind==='vine'?(rana.phase>1?'whip':'rise'):kind==='spore'?(i%2?'drift':'cloud'):'launch');}}
