 const dist=Math.hypot(nessie.x-boss.x,nessie.y-boss.y);if(dist<146&&nessie.y>waterSurface()+25&&boss.hitCooldown<=0){if(dashTime>0&&boss.vulnerable)ranaHit();else if(!boss.vulnerable&&s!=='stagger'&&s!=='phaseTransition')hurt(boss.x);}
