function ranaHit(){boss.hp--;boss.hitCooldown=1.1;boss.vulnerable=false;bossLeapReady=true;score+=450;invincible=1;nessie.vx=-nessie.face*280;nessie.vy=-100;dashTime=0;rana.hitStop=reducedMotion?.045:boss.hp<=0?.15:.095;rana.recoil=1;bossImpact(boss);ranaBurst(boss.x,boss.y,45,'#a9ffe0',270);rana.rings=[];rana.sparks.push({x:boss.x,y:boss.y,age:0,life:.65,impact:true});projectiles=[];finalHazards=[];popups.push({x:nessie.x,y:nessie.y-100,text:'↟ ×2',life:1.35,color:'#eccbff'});tone(180,.18);rana.queue=[];if(boss.hp<=0){ranaNext('defeated');return;}const phase=ranaPhase();rana.pendingTransition=phase!==rana.phase;rana.phase=phase;ranaNext('stagger');}
function updateRanaEffects(dt){for(const ring of rana.rings){ring.r+=ring.speed*dt;ring.life-=dt;const a=Math.atan2(nessie.y-ring.y,nessie.x-ring.x),safe=Math.abs(ranaAngle(a-ring.gap))<ring.gapWidth;if(nessie.y>waterSurface()+22&&!safe&&Math.abs(Math.hypot(nessie.x-ring.x,nessie.y-ring.y)-ring.r)<29)hurt(ring.x);}rana.rings=rana.rings.filter(r=>r.life>0);for(const p of rana.sparks){p.age+=dt;p.life-=dt;}rana.sparks=rana.sparks.filter(p=>p.life>0);if(rana.sparks.length>30)rana.sparks.splice(0,rana.sparks.length-30);if(rana.trails.length>16)rana.trails.shift();for(const p of rana.trails)p.life-=dt;rana.trails=rana.trails.filter(p=>p.life>0);if(rana.state==='lunge')rana.trails.push({x:boss.x,y:boss.y,life:.24});}
function ranaVinePoints(h){const strength=h.strength,top=865-strength*350;const bend=h.variant==='whip'?Math.sin(h.age*3)*100:20;return [{x:h.x-15,y:865},{x:h.x+bend,y:top+180},{x:h.x-bend*.6,y:top+55},{x:h.x+bend*.4,y:top}];}
function updateRanaHazards(dt){for(const h of finalHazards){h.age+=dt;h.warning=h.age<0;h.active=h.age>=0&&h.age<h.duration;h.strength=h.active?Math.sin(clamp(h.age/h.duration,0,1)*Math.PI):0;if(h.variant==='drift'&&h.active){h.x=h.bx+Math.sin(h.age)*60;h.y=h.by+h.age*20;}if(!h.active)continue;if(h.kind==='vine'){const pts=ranaVinePoints(h);for(let i=1;i<pts.length;i++)if(ranaSegmentDistance(nessie.x,nessie.y,pts[i-1].x,pts[i-1].y,pts[i].x,pts[i].y)<32)hurt(h.x);}else if(h.kind==='spore'){if(Math.hypot(nessie.x-h.x,nessie.y-h.y)<70+35*h.strength)hurt(h.x);}else{const height=370*h.strength;if(Math.abs(nessie.x-h.x)<46&&nessie.y<h.y+20&&nessie.y>h.y-height){if(!leap.active)nessie.vy-=dt*430;hurt(h.x);}}}finalHazards=finalHazards.filter(h=>h.age<h.duration+.35);}
function updateRanaHud(){const hud=$('boss-hud');hud.classList.toggle('rana-fight',isRana()&&mode!=='trial');if(!isRana()||mode==='trial'||!rana)return;hud.dataset.phase=String(rana.phase);if(boss?.active){$('boss-name').textContent='Rana Rex · Laser Frog';hud.setAttribute('aria-label','Rana Rex: '+RANA_PHASES[rana.phase-1]);const cue=boss.vulnerable?'boost':/Charge|Prepare|Command/.test(rana.state)?'warning':bossLeapReady&&rana.state.startsWith('retaliation')?'double':'shield';setIconCue($('boss-cue'),cue,boss.vulnerable?'Green opening: boost into Rana':cue==='double'?'Up + Boost: double flip escape':'Read Rana’s attack warning');let pips=$('rana-pips');if(!document.getElementById('rana-pips')){pips=document.createElement('div');pips.id='rana-pips';pips.className='rana-pips';$('boss-name').parentElement.appendChild(pips);}setHtmlIfChanged(pips,Array.from({length:6},(_,i)=>'<i class="'+(i<boss.hp?'full':'empty')+'" data-phase="'+(i<2?3:i<4?2:1)+'"></i>').join(''));pips.setAttribute('aria-label',boss.hp+' of 6 hits remaining, phase '+rana.phase);}}
